/*
 * The diagram format: boxes and arrows an agent writes as `<name>.diagram.json` (a workflow, a flow between screens, the states of a case).
 * Plain data drawn by `DiagramView`: nothing in it is built or runs. It is a superset of a maquette's `workflow` (`states` and `transitions`
 * are aliases of `nodes` and `edges`), so a maquette hands its workflow to the same reader. Documented in registry/README.md ("Diagram viewer").
 * Model output is untrusted: `parseDiagram` keeps what it understands, bounds every list and string, and never throws.
 */

/** The format version this viewer writes and reads. A file without `version` is read as version 1. */
export const DIAGRAM_FORMAT_VERSION = 1;

/** A diagram file as written in format v1. */
export interface DiagramFileV1 {
  /** Absent means 1. */
  readonly version?: 1;
  readonly title?: string;
  /** The boxes, in reading order; the first is where the flow starts. A bare string is a node whose label is its id. `states` is an alias. */
  readonly nodes: readonly ({ readonly id: string; readonly label?: string; readonly group?: string } | string)[];
  /** The arrows between nodes (`transitions` is an alias; `on` is an alias of `label`). `by`: who acts. */
  readonly edges?: readonly { readonly from: string; readonly to: string; readonly label?: string; readonly on?: string; readonly by?: string }[];
  /** Named groups a node can belong to (its `group`); a group named by a node but not listed here is named by its id. */
  readonly groups?: readonly ({ readonly id: string; readonly label?: string } | string)[];
  /** Node ids of one path through the diagram, drawn stronger with the arrows between consecutive nodes. */
  readonly path?: readonly string[];
  /** One short paragraph under the diagram. */
  readonly note?: string;
}

export interface DiagramNode { readonly id: string; readonly label: string; readonly group?: string | undefined }
export interface DiagramEdge { readonly from: string; readonly to: string; readonly label: string; readonly by: string }
export interface DiagramGroup { readonly id: string; readonly label: string }
/** A diagram ready to draw: every field read, bounded and defaulted; edges and the path only name known nodes. */
export interface Diagram {
  readonly title: string;
  readonly nodes: readonly DiagramNode[];
  readonly edges: readonly DiagramEdge[];
  readonly groups: readonly DiagramGroup[];
  readonly path: readonly string[];
  readonly note: string;
}

/**
 * The outcome of reading a file. `version` is the file's declared version (1 when absent); a version above `DIAGRAM_FORMAT_VERSION`
 * is read as v1, best effort. `invalid` is not JSON (`json`) or has no node to draw (`shape`).
 */
export type DiagramParse =
  | { readonly kind: 'ok'; readonly diagram: Diagram; readonly version: number }
  | { readonly kind: 'invalid'; readonly reason: 'json' | 'shape'; readonly version: number | undefined };

const str = (value: unknown, max = 400): string => typeof value === 'string' ? value.slice(0, max) : typeof value === 'number' && Number.isFinite(value) ? String(value) : '';
const arr = (value: unknown, max: number): readonly unknown[] => Array.isArray(value) ? value.slice(0, max) : [];
const obj = (value: unknown): Record<string, unknown> => value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};

/** Reads a diagram (its JSON text, or an already parsed value such as a maquette's `workflow`). Never throws. */
export function parseDiagram(input: unknown): DiagramParse {
  let raw: unknown = input;
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw); } catch { return { kind: 'invalid', reason: 'json', version: undefined }; }
  }
  const spec = obj(raw);
  const declared = spec['version'];
  const version = declared === undefined ? 1 : typeof declared === 'number' && Number.isSafeInteger(declared) && declared >= 1 ? declared : undefined;
  if (version === undefined) return { kind: 'invalid', reason: 'shape', version: undefined };
  const seen = new Set<string>();
  const nodes = arr(spec['nodes'] ?? spec['states'], 40).map((value): DiagramNode | null => {
    const node = obj(value), id = str(node['id'], 60) || str(value, 60);
    if (!id || seen.has(id)) return null;
    seen.add(id);
    const group = str(node['group'], 60);
    return { id, label: str(node['label'], 80) || id, ...(group ? { group } : {}) };
  }).filter((node): node is DiagramNode => node !== null);
  if (!nodes.length) return { kind: 'invalid', reason: 'shape', version };
  const edges = arr(spec['edges'] ?? spec['transitions'], 80).map((value): DiagramEdge => {
    const edge = obj(value);
    return { from: str(edge['from'], 60), to: str(edge['to'], 60), label: str(edge['label'] ?? edge['on'], 80), by: str(edge['by'], 40) };
  }).filter(edge => seen.has(edge.from) && seen.has(edge.to));
  const listed = arr(spec['groups'], 12).map((value): DiagramGroup | null => {
    const group = obj(value), id = str(group['id'], 60) || str(value, 60);
    return id ? { id, label: str(group['label'], 80) || id } : null;
  }).filter((group): group is DiagramGroup => group !== null);
  const named = [...new Set(nodes.flatMap(node => node.group ? [node.group] : []))].filter(id => !listed.some(group => group.id === id)).map(id => ({ id, label: id }));
  return { kind: 'ok', version, diagram: {
    title: str(spec['title'], 120), nodes, edges, groups: [...listed, ...named],
    path: arr(spec['path'], 20).map(id => str(id, 60)).filter(id => seen.has(id)),
    note: str(spec['note'], 600),
  } };
}

/** True for a path the built-in diagram kind draws: a `.diagram.json` file. */
export const isDiagramPath = (path: string): boolean => /\.diagram\.json$/i.test(path);

/* The diagram viewer's words in English and French. `locale` picks the base set; a host's `labels` still override any of them. */

export type DiagramLocale = 'en' | 'fr';

export const defaultDiagramLabels = {
  /** The kind's name on the artifact card and in the panel bar. */
  kind: 'Diagram',
  transitionBy: (by: string) => `by ${by}`,
  newerTitle: 'Made with a newer version',
  newer: (version: number) => `This diagram uses format version ${version}. This viewer reads version 1: parts it does not know may be missing.`,
  errorTitle: 'This diagram cannot be shown',
  invalidJson: 'The file is not valid JSON. Ask the agent to present it again.',
  invalidShape: 'The file has no node to draw (a diagram needs "nodes": [{ "id", "label" }]).',
};
export type DiagramLabels = typeof defaultDiagramLabels;

/** Typed as `DiagramLabels`, so a key added in English must be added here too. */
export const frenchDiagramLabels: DiagramLabels = {
  kind: 'Diagramme',
  transitionBy: by => `par ${by}`,
  newerTitle: 'Fait avec une version plus récente',
  newer: version => `Ce diagramme utilise la version ${version} du format. Cet afficheur lit la version 1 : ce qu’il ne connaît pas peut manquer.`,
  errorTitle: 'Ce diagramme ne peut pas être affiché',
  invalidJson: 'Le fichier n’est pas du JSON valide. Demandez à l’agent de le présenter à nouveau.',
  invalidShape: 'Le fichier n’a aucun nœud à dessiner (un diagramme a besoin de « nodes » : [{ "id", "label" }]).',
};

/** The viewer's words for `locale` (English by default) with the host's overrides. */
export const diagramLabelsFor = (locale: DiagramLocale | undefined, labels?: Partial<DiagramLabels>): DiagramLabels =>
  ({ ...(locale === 'fr' ? frenchDiagramLabels : defaultDiagramLabels), ...labels });

'use client';

// A diagram drawn as an SVG and a legend: nodes in layers by distance from the first node, one arrow per edge with a numbered badge, and a
// numbered legend under it that says what happens and who acts (labels of any length). Layers run left to right while they fit the box; in
// a narrow box (a phone) they run top to bottom instead. A diagram still wider than its box scrolls inside it, never the page. A node's
// group is a muted second line in its box. No layout library: the layered layout is a breadth-first pass over the edges.
import { useEffect, useId, useRef, useState } from 'react';
import { Badge } from '@/components/ui/badge';
import type { Diagram } from './diagram';

const H1 = 44, H2 = 54, W_WIDE = 148, GX = 72, GY = 36, VX = 16, VY = 56, LOOP = 36;

type Point = { readonly x: number; readonly y: number };

/** Each node's layer: the shortest number of edges from the first node; nodes it never reaches come after, one layer each. */
function layers(diagram: Diagram): Map<number, string[]> {
  const { nodes, edges } = diagram;
  const depth = new Map<string, number>([[nodes[0]!.id, 0]]);
  for (let changed = true, guard = 0; changed && guard < 50; guard++) {
    changed = false;
    for (const edge of edges) if (depth.has(edge.from) && !depth.has(edge.to)) { depth.set(edge.to, depth.get(edge.from)! + 1); changed = true; }
  }
  let extra = Math.max(0, ...depth.values()) + 1;
  for (const node of nodes) if (!depth.has(node.id)) depth.set(node.id, extra++);
  const columns = new Map<number, string[]>();
  for (const node of nodes) { const d = depth.get(node.id)!; columns.set(d, [...(columns.get(d) ?? []), node.id]); }
  return columns;
}

/** The SVG path of an edge and where its number sits. */
function arrow(a: Point, b: Point, W: number, H: number, vertical: boolean): { d: string; x: number; y: number } {
  if (!vertical) {
    // Next layer: right edge to left edge. Same layer, below: straight down. Otherwise (back, or skipping a layer): a loop under both boxes.
    const kind = b.x > a.x && b.x - a.x <= W + GX ? 'forward' : b.x === a.x && b.y > a.y ? 'down' : 'back';
    const x1 = kind === 'forward' ? a.x + W : a.x + W / 2, y1 = kind === 'forward' ? a.y + H / 2 : a.y + H;
    const x2 = kind === 'forward' ? b.x : b.x + W / 2, y2 = kind === 'forward' ? b.y + H / 2 : kind === 'down' ? b.y : b.y + H;
    const d = kind === 'forward' ? `M${x1} ${y1} C${x1 + GX / 2} ${y1} ${x2 - GX / 2} ${y2} ${x2} ${y2}` : kind === 'down' ? `M${x1} ${y1} L${x2} ${y2}` : `M${x1} ${y1} C${x1} ${y1 + 30} ${x2} ${y2 + 30} ${x2} ${y2}`;
    return { d, x: kind === 'down' ? x1 + 12 : (x1 + x2) / 2, y: kind === 'back' ? Math.max(y1, y2) + 22 : (y1 + y2) / 2 };
  }
  // Next layer: bottom edge to top edge. Same row: side to side. Otherwise (back, or skipping a layer): a loop on the right.
  const kind = b.y > a.y && b.y - a.y <= H + VY ? 'forward' : b.y === a.y ? 'across' : 'back';
  const right = b.x > a.x;
  const x1 = kind === 'forward' ? a.x + W / 2 : kind === 'across' ? (right ? a.x + W : a.x) : a.x + W, y1 = kind === 'forward' ? a.y + H : a.y + H / 2;
  const x2 = kind === 'forward' ? b.x + W / 2 : kind === 'across' ? (right ? b.x : b.x + W) : b.x + W, y2 = kind === 'forward' ? b.y : b.y + H / 2;
  const out = Math.max(x1, x2) + LOOP - 8;
  const d = kind === 'forward' ? `M${x1} ${y1} C${x1} ${y1 + VY / 2} ${x2} ${y2 - VY / 2} ${x2} ${y2}` : kind === 'across' ? `M${x1} ${y1} L${x2} ${y2}` : `M${x1} ${y1} C${out} ${y1} ${out} ${y2} ${x2} ${y2}`;
  return { d, x: kind === 'back' ? out - 6 : (x1 + x2) / 2, y: (y1 + y2) / 2 };
}

const clip = (text: string, fit: number) => text.length > fit ? `${text.slice(0, fit - 1)}…` : text;

/** The words the view needs (a maquette's labels have them too). */
export interface DiagramViewLabels { readonly transitionBy: (by: string) => string }

/**
 * The diagram and its legend. `highlight`: node ids of a path (the diagram's own `path` by default), drawn stronger with the arrows between
 * consecutive nodes of it.
 */
export function DiagramView({ diagram, highlight = diagram.path, labels }: { readonly diagram: Diagram; readonly highlight?: readonly string[]; readonly labels: DiagramViewLabels }) {
  const { nodes, edges, groups } = diagram;
  const box = useRef<HTMLDivElement>(null);
  const [room, setRoom] = useState(0);
  const marker = `diagram-arrow-${useId().replace(/:/g, '')}`;
  useEffect(() => {
    const element = box.current;
    if (!element) return undefined;
    const measure = () => setRoom(element.clientWidth);
    measure();
    if (typeof ResizeObserver === 'undefined') return undefined;
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const H = nodes.some(node => node.group) ? H2 : H1;
  const columns = layers(diagram);
  const count = Math.max(...columns.keys()) + 1, widest = Math.max(...[...columns.values()].map(ids => ids.length));
  const vertical = room > 0 && 16 + count * W_WIDE + (count - 1) * GX > room;
  const W = vertical ? Math.max(104, Math.min(W_WIDE, Math.floor((room - 16 - LOOP - (widest - 1) * VX) / widest))) : W_WIDE;
  const pos = new Map<string, Point>();
  for (const [d, ids] of columns) ids.forEach((id, i) => pos.set(id, vertical ? { x: 8 + i * (W + VX), y: 8 + d * (H + VY) } : { x: 8 + d * (W + GX), y: 8 + i * (H + GY) }));
  const points = [...pos.values()];
  const width = (vertical ? LOOP : 16) + Math.max(...points.map(p => p.x)) + W + 8, height = (vertical ? 16 : 40) + Math.max(...points.map(p => p.y)) + H;
  const on = new Set(highlight);
  const steps = new Set(highlight.slice(1).map((id, i) => `${highlight[i]}\n${id}`));
  const lit = (from: string, to: string) => steps.has(`${from}\n${to}`);
  const label = (id: string) => nodes.find(node => node.id === id)?.label ?? id;
  const groupLabel = (id: string | undefined) => id ? groups.find(group => group.id === id)?.label ?? id : '';
  const fit = Math.floor((W - 16) / 7);
  return <div data-testid="diagram-view" className="flex min-w-0 flex-col gap-4">
    <div ref={box} data-testid="diagram" data-layout={vertical ? 'vertical' : 'horizontal'} className="min-w-0 overflow-x-auto">
      <svg role="img" aria-label={nodes.map(node => node.label).join(' → ')} width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="block">
        <defs><marker id={marker} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" className="fill-muted-foreground" /></marker></defs>
        {edges.map((edge, i) => {
          const path = arrow(pos.get(edge.from)!, pos.get(edge.to)!, W, H, vertical);
          const strong = lit(edge.from, edge.to);
          return <g key={i} data-edge={`${edge.from}→${edge.to}`} data-lit={strong || undefined}>
            <path d={path.d} fill="none" className={strong ? 'stroke-primary' : 'stroke-muted-foreground/60'} strokeWidth={strong ? 2 : 1.25} markerEnd={`url(#${marker})`} />
            <circle cx={path.x} cy={path.y} r="9" className={strong ? 'fill-primary stroke-primary' : 'fill-background stroke-border'} />
            <text x={path.x} y={path.y + 3.5} textAnchor="middle" fontSize="10" className={strong ? 'fill-primary-foreground' : 'fill-foreground'}>{i + 1}</text>
          </g>;
        })}
        {nodes.map(node => {
          const p = pos.get(node.id)!, strong = on.has(node.id), group = groupLabel(node.group);
          return <g key={node.id} data-node={node.id} data-group={node.group} data-lit={strong || undefined}>
            <rect x={p.x} y={p.y} width={W} height={H} rx="10" className={strong ? 'fill-primary/10 stroke-primary' : 'fill-card stroke-border'} strokeWidth={strong ? 2 : 1} />
            <text x={p.x + W / 2} y={p.y + (group ? 22 : H / 2 + 4)} textAnchor="middle" fontSize="12" className="fill-foreground">{clip(node.label, fit)}<title>{node.label}</title></text>
            {group && <text x={p.x + W / 2} y={p.y + 40} textAnchor="middle" fontSize="10" className="fill-muted-foreground">{clip(group, fit + 2)}</text>}
          </g>;
        })}
      </svg>
    </div>
    {edges.length > 0 && <ol data-testid="diagram-legend" className="m-0 grid list-none gap-x-6 gap-y-2 p-0 text-sm sm:grid-cols-2">
      {edges.map((edge, i) => <li key={i} className="flex min-w-0 items-start gap-2">
        <Badge variant={lit(edge.from, edge.to) ? 'default' : 'outline'} className="tabular-nums">{i + 1}</Badge>
        <span className="min-w-0 text-pretty"><span className="font-medium">{label(edge.from)} → {label(edge.to)}</span>{edge.label && <>: {edge.label}</>}
          {edge.by && <span className="text-muted-foreground"> ({labels.transitionBy(edge.by)})</span>}</span>
      </li>)}
    </ol>}
    {diagram.note && <p data-testid="diagram-note" className="m-0 text-sm text-pretty text-muted-foreground">{diagram.note}</p>}
  </div>;
}

'use client';

// The diagram viewer: an agent's `*.diagram.json` (format v1) drawn by `DiagramView`, with its highlighted path and note. `diagramKind` (diagram-kind.ts) is
// the kind the pi-app artifact panel uses by default for `.diagram.json` files; an app's own kind in `artifactKinds` wins. The maquette
// viewer draws its workflow ("How it works") with the same `DiagramView`. It draws data only: nothing in the file runs.
import { useMemo } from 'react';
import { InfoIcon, TriangleAlertIcon } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { DIAGRAM_FORMAT_VERSION, parseDiagram } from './diagram';
import { diagramLabelsFor } from './diagram-labels';
import type { DiagramLabels, DiagramLocale } from './diagram-labels';
import { DiagramView } from './diagram-view';

export { DIAGRAM_FORMAT_VERSION, isDiagramPath, parseDiagram } from './diagram';
export type { Diagram, DiagramEdge, DiagramFileV1, DiagramGroup, DiagramNode, DiagramParse } from './diagram';
export { DiagramView } from './diagram-view';
export type { DiagramViewLabels } from './diagram-view';
export { defaultDiagramLabels, diagramLabelsFor, frenchDiagramLabels } from './diagram-labels';
export type { DiagramLabels, DiagramLocale } from './diagram-labels';

export interface DiagramViewerProps {
  /** The file's text (JSON). */
  readonly text: string;
  /** The base words: English by default. */
  readonly locale?: DiagramLocale | undefined;
  /** Any word over the locale's. */
  readonly labels?: Partial<DiagramLabels> | undefined;
}

/** A diagram file; a newer format version shows a notice, an unreadable file an inline error. */
export function DiagramViewer({ text, locale, labels: given }: DiagramViewerProps) {
  const labels = useMemo(() => diagramLabelsFor(locale, given), [locale, given]);
  const parsed = useMemo(() => parseDiagram(text), [text]);
  const newer = parsed.version !== undefined && parsed.version > DIAGRAM_FORMAT_VERSION;
  return <section data-boring="diagram-viewer" data-state={parsed.kind} aria-label={parsed.kind === 'ok' ? parsed.diagram.title || labels.kind : labels.kind}
    className="mx-auto flex w-full max-w-5xl min-w-0 flex-col gap-3 px-3 pt-2 pb-4 sm:px-6">
    {newer && <Alert data-testid="diagram-newer"><InfoIcon aria-hidden="true" /><AlertTitle>{labels.newerTitle}</AlertTitle><AlertDescription>{labels.newer(parsed.version!)}</AlertDescription></Alert>}
    {parsed.kind === 'ok' ? <DiagramView diagram={parsed.diagram} labels={labels} />
      : <Alert variant="destructive" data-testid="diagram-error" data-reason={parsed.reason}><TriangleAlertIcon aria-hidden="true" /><AlertTitle>{labels.errorTitle}</AlertTitle>
        <AlertDescription>{parsed.reason === 'json' ? labels.invalidJson : labels.invalidShape}</AlertDescription></Alert>}
  </section>;
}

'use client';

import { lazy } from 'react';
import type { ComponentType, ReactNode } from 'react';
import { WorkflowIcon } from 'lucide-react';
import { isDiagramPath } from './diagram';
import { diagramLabelsFor } from './diagram-labels';
import type { DiagramLabels, DiagramLocale } from './diagram-labels';

const DiagramViewer = lazy(() => import('./diagram-viewer').then(module => ({ default: module.DiagramViewer })));

/**
 * The artifact kind of a diagram file (structurally an `ArtifactKind` of pi-artifacts): it matches `*.diagram.json`, names it, gives its icon
 * and draws it with `DiagramViewer`, loaded on first open. Pass it, or your own, in `artifactKinds`; kinds an app passes are consulted first.
 */
export interface DiagramKind {
  readonly match: (target: { readonly resource: { readonly path: string } }) => boolean;
  readonly label: string;
  readonly icon: ComponentType<{ readonly className?: string; readonly 'aria-hidden'?: boolean | 'true' }>;
  readonly renderer: (props: { readonly text: string }) => ReactNode;
}

/** A diagram kind in `locale` ("Diagram" in English, "Diagramme" in French) with any word overridden. */
export function createDiagramKind({ locale, labels }: { readonly locale?: DiagramLocale | undefined; readonly labels?: Partial<DiagramLabels> | undefined } = {}): DiagramKind {
  return {
    match: target => isDiagramPath(target.resource.path),
    label: diagramLabelsFor(locale, labels).kind,
    icon: WorkflowIcon,
    renderer: ({ text }) => <DiagramViewer text={text} locale={locale} labels={labels} />,
  };
}

/** The built-in diagram kind, in English. */
export const diagramKind: DiagramKind = createDiagramKind();
